        "outputs": [
          ["python_code", "string"],
          ["result", "string"]
        ],
        "code": "import traceback
import sys
from io import StringIO

def main(input_code: str):
    # Initialize result
    result = ""

    try:
        # Try to compile the code first to check syntax
        compile(input_code, '<string>', 'exec')
        python_code = input_code
    except SyntaxError as e:
        # If there's a syntax error, try to fix common issues
        python_code = fix_common_syntax_errors(input_code)
        try:
            compile(python_code, '<string>', 'exec')
        except SyntaxError as e:
            return {
                "python_code": input_code,
                "result": f"Syntax Error: {str(e)}"
            }

    try:
        # Capture stdout to get print outputs
        old_stdout = sys.stdout
        sys.stdout = captured_output = StringIO()

        # Execute the code
        exec(python_code)

        # Get the output
        sys.stdout = old_stdout
        result = captured_output.getvalue()

        if not result:
            result = "Code executed successfully with no output."

    except Exception as e:
        sys.stdout = old_stdout
        result = f"Execution Error: {str(e)}\n{traceback.format_exc()}"

    return {
        "python_code": python_code,
        "result": result
    }

def fix_common_syntax_errors(code: str) -> str:
    # Simple fixes for common syntax issues
    lines = code.split('\n')
    fixed_lines = []

    for line in lines:
        # Fix missing colons in control structures
        stripped = line.strip()
        if (stripped.startswith('if ') or stripped.startswith('for ') or 
            stripped.startswith('while ') or stripped.startswith('def ') or
            stripped.startswith('class ')) and not stripped.endswith(':'):
            line = line + ':'

        # Fix missing spaces around operators if needed
        fixed_lines.append(line)

    return '\n'.join(fixed_lines)"
      }
